import pygame, sys, io
import asyncio 

plrHex = "#3498DB"
coinHex = "#F1C40F"
platHex = "#2ECC71"
bgHex = "#1E1E2E"

plrImgHex = ""
coinImgHex = ""

w, h = 800, 600
g = 0.4

pygame.init()
scr = pygame.display.set_mode((w, h))
pygame.display.set_caption("Platformer")
clock = pygame.time.Clock()


def load_hex_img(hex_str, default_size):
    if not hex_str.strip():
        return None
    try:
        img_bytes = bytes.fromhex(hex_str.strip())
        img = pygame.image.load(io.BytesIO(img_bytes)).convert_alpha()
        return pygame.transform.scale(img, default_size)
    except Exception:
        return None


class Player(pygame.sprite.Sprite):
    def __init__(self, x, y, WASD):
        super().__init__()
        
        img = load_hex_img(plrImgHex, (32, 48))
        if img:
            self.image = img
        else:
            self.image = pygame.Surface((32, 48))
            self.image.fill(pygame.Color(plrHex))
            
        self.wasd = WASD
        self.rect = self.image.get_rect(topleft=(x, y))
        self.vy = 0
        self.onGround = False

    def update(self, plats):
        k = pygame.key.get_pressed()

        # move
        if (k[pygame.K_LEFT] and not self.wasd) or (k[pygame.K_a] and self.wasd):
            self.rect.x -= 5
        if (k[pygame.K_RIGHT] and not self.wasd) or (k[pygame.K_d] and self.wasd):
            self.rect.x += 5
        if ((k[pygame.K_UP] and not self.wasd) or (k[pygame.K_w] and self.wasd)) and self.onGround:
            self.vy = -13
            self.onGround = False

        self.vy += g
        self.rect.y += self.vy

        # collision
        self.onGround = False
        for p in plats:
            if self.rect.colliderect(p.rect):
                if self.vy > 0 and self.rect.bottom - self.vy <= p.rect.top + 10:
                    self.rect.bottom = p.rect.top
                    self.vy = 0
                    self.onGround = True


class Platform(pygame.sprite.Sprite):
    def __init__(self, x, y, pw, ph, *args):
        super().__init__()
        self.image = pygame.Surface((pw, ph))
        self.image.fill(pygame.Color(platHex))
        self.rect = self.image.get_rect(topleft=(x, y))

        self.mode = None
        self.dx = self.dy = 0
        self.step = 0
        self.coins = []

        i = 0
        if args and type(args[0]) is bool:
            if args[0]:  # true -> bouncing
                self.mode = "bounce"
                self.dx, self.dy = args[1], args[2]
                i = 3
            else:        # false -> scrolling
                self.mode = "scroll"
                self.dx, self.dy = args[1], args[2]
                self.startPos, self.endPos = list(args[3]), list(args[4])
                i = 5

                # extra scrolling stream
                if len(args) > 5 and type(args[5]) is int:
                    cnt = args[5]
                    i = 6
                    for k in range(1, cnt):
                        sx = args[3][0] + (args[4][0] - args[3][0]) * (k / cnt)
                        sy = args[3][1] + (args[4][1] - args[3][1]) * (k / cnt)
                        sp = Platform(sx, sy, pw, ph, False, args[1], args[2], args[3], args[4], 1, *args[6:])
                        plats.add(sp)
                        allSprs.add(sp)

        # initialising coins relative to platforms
        for cRel in args[i:]:
            c = Coin(x + cRel[0], y + cRel[1])
            self.coins.append(c)
            coins.add(c)
            allSprs.add(c)

    def update(self):
        if not self.mode:
            return

        mx, my = self.dx, self.dy

        if self.mode == "bounce":
            self.step += 1
            if self.step >= 100:
                self.dx, self.dy = -self.dx, -self.dy
                self.step = 0
        elif self.mode == "scroll":
            # Check if platform reached end position on active movement axes
            reached_x = (self.dx == 0) or (abs(self.rect.x - self.endPos[0]) <= abs(self.dx))
            reached_y = (self.dy == 0) or (abs(self.rect.y - self.endPos[1]) <= abs(self.dy))
            if reached_x and reached_y:
                mx = self.startPos[0] - self.rect.x
                my = self.startPos[1] - self.rect.y

        self.rect.x += mx
        self.rect.y += my

        for c in self.coins:
            if c.alive():
                c.rect.x += mx
                c.rect.y += my


class Coin(pygame.sprite.Sprite):
    def __init__(self, x, y):
        super().__init__()
        
        img = load_hex_img(coinImgHex, (20, 20))
        if img:
            self.image = img
        else:
            self.image = pygame.Surface((20, 20))
            self.image.fill(pygame.Color(coinHex))

        self.rect = self.image.get_rect(topleft=(x, y))


allSprs = pygame.sprite.Group()
plats = pygame.sprite.Group()
coins = pygame.sprite.Group()


def scrScroll():
    margin = 200
    dx = dy = 0

    if player1.rect.left < margin:
        dx = margin - player1.rect.left
        player1.rect.left = margin
    elif player1.rect.right > w - margin:
        dx = (w - margin) - player1.rect.right
        player1.rect.right = w - margin

    if player1.rect.top < margin:
        dy = margin - player1.rect.top
        player1.rect.top = margin

    if dx or dy:
        for s in allSprs:
            if s != player1 and s != player2:
                s.rect.x += dx
                s.rect.y += dy
                if isinstance(s, Platform) and s.mode == "scroll":
                    s.startPos[0] += dx
                    s.startPos[1] += dy
                    s.endPos[0] += dx
                    s.endPos[1] += dy


player1 = Player(100, 300, True)
player2 = Player(200, 300, False)
allSprs.add(player1, player2)

# still
p1 = Platform(50, 450, 300, 30, (50, -30), (150, -30))

# bounce
p2 = Platform(400, 380, 150, 20, True, 2, 0, (60, -30))

# 3x scroll
p3 = Platform(100, 220, 120, 20, False, 2, 0, (100, 220), (700, 220), 2, (40, -30))

p4 = Platform(120, 80, 120, 20, False, 2, 0, (120, 80), (800, 80), 2, (40, -30))

p5 = Platform(90, -90, 120, 20, False, 2, 0, (90, -90), (500, -90), 2, (40, -30))


for p in (p1, p2, p3, p4, p5):
    plats.add(p)
    allSprs.add(p)

async def main():
    while True:
        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

        plats.update()
        player1.update(plats)
        player2.update(plats)
        scrScroll()

        # Check coin collisions for both players
        if pygame.sprite.spritecollide(player1, coins, True) or pygame.sprite.spritecollide(player2, coins, True):
            print("Coin collected!")

        scr.fill(pygame.Color(bgHex))
        allSprs.draw(scr)
        pygame.display.flip()
        clock.tick(60)
        await asyncio.sleep(0)

asyncio.run(main())
